                cnt[v] += 1
    if not cnt:
        return grid
    frame_col = max(cnt, key=cnt.get)

    # ---- locate interior zero regions (holes) ----
    # BFS from all border zeros → marks external zeros
    external = [[False] * m for _ in range(n)]
