                            q.append((nx, ny))
                holes.append(comp)

    # ---- find all non‑frame coloured components (possible fillers) ----
    visited = [[False] * m for _ in range(n)]
    shape_dict = {}               # shape → list of (colour, component)
    for i in range(n):
        for j in range(m):
            col = grid[i][j]
            if col != 0 and col != frame_col and not visited[i][j]:
                comp = []
                q = deque([(i, j)])
                visited[i][j] = True
                while q:
                    x, y = q.popleft()
                    comp.append((x, y))
                    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+di, y+dj
                        if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == col:
                            visited[nx][ny] = True
                            q.append((nx, ny))
                # encode shape as a binary matrix
                rows = [c[0] for c in comp]
                cols = [c[1] for c in comp]
                r0, r1 = min(rows), max(rows)
                c0, c1 = min(cols), max(cols)
                h, w = r1 - r0 + 1, c1 - c0 + 1
                shape = [[0] * w for _ in range(h)]
                for x, y in comp:
                    shape[x - r0][y - c0] = 1
                shape_key = tuple(tuple(row) for row in shape)
                shape_dict.setdefault(shape_key, []).append((col, comp))

    # ---- match each hole with a filler of identical shape ----
    for hole in holes:
        # encode hole shape
        rows = [c[0] for c in hole]
        cols = [c[1] for c in hole]
        r0, r1 = min(rows), max(rows)
        c0, c1 = min(cols), max(cols)
        h, w = r1 - r0 + 1, c1 - c0 + 1
        shape = [[0] * w for _ in range(h)]
        for x, y in hole:
            shape[x - r0][y - c0] = 1
        shape_key = tuple(tuple(row) for row in shape)

        if shape_key in shape_dict and shape_dict[shape_key]:
            filler_col, filler_comp = shape_dict[shape_key].pop(0)
            # erase filler where it originally was
            for x, y in filler_comp:
                grid[x][y] = 0
            # fill the hole with the filler colour
            for x, y in hole:
                grid[x][y] = filler_col
        # if no matching filler is found, leave the hole unchanged

    return grid

